int process_gif_image(struct iwgifrcontext *rctx) {
    if (!rctx || !rctx->file) {
        return 0;
    }

    // Read image header
    uint8_t header[6];
    if (fread(header, 1, 6, rctx->file) != 6) {
        return 0;
    }

    rctx->width = (header[0] << 8) | header[1];
    rctx->height = (header[2] << 8) | header[3];

    // Check for valid dimensions
    if (rctx->width <= 0 || rctx->height <= 0) {
        return 0;
    }

    // Parse interlacing and color table info
    rctx->interlaced = (header[4] >> 6) & 0x01;
    int has_local_table = (header[4] & 0x80) >> 7;
    int color_table_size = 2 << ((header[4] & 0x07) + 1);

    if (has_local_table) {
        rctx->local_color_table = malloc(color_table_size * sizeof(uint8_t) * 3);
        if (!rctx->local_color_table) {
            return 0;
        }
        if (fread(rctx->local_color_table, 3, color_table_size, rctx->file) != color_table_size) {
            free(rctx->local_color_table);
            rctx->local_color_table = NULL;
            return 0;
        }
    }

    // Handle transparency
    if (rctx->disposal_method == 2) {
        rctx->transparent_index = rctx->transparency_index;
        // Adjust color table to mark the transparent index
        if (rctx->local_color_table) {
            rctx->local_color_table[rctx->transparent_index * 3] = 0;
            rctx->local_color_table[rctx->transparent_index * 3 + 1] = 0;
            rctx->local_color_table[rctx->transparent_index * 3 + 2] = 0;
        }
    }

    // Read LZW code size
    uint8_t lzw_code_size;
    if (fread(&lzw_code_size, 1, 1, rctx->file) != 1) {
        return 0;
    }

    if (lzw_code_size < 2 || lzw_code_size > 12) {
        return 0;
    }

    // Initialize screen context
    rctx->current_x = 0;
    rctx->current_y = 0;
    rctx->image_data = NULL;

    int success = 1;
    uint8_t subblock_size;
    while (fread(&subblock_size, 1, 1, rctx->file) == 1 && subblock_size > 0) {
        uint8_t *subblock = malloc(subblock_size);
        if (!subblock) {
            success = 0;
            break;
        }
        if (fread(subblock, 1, subblock_size, rctx->file) != subblock_size) {
            free(subblock);
            success = 0;
            break;
        }
        success &= lzw_decode(rctx, subblock, subblock_size);
        free(subblock);
    }

    return success;
}

int iwgif_read_image(struct iwgifrcontext *rctx) {
    unsigned char header[6];
    unsigned char image_descriptor[2];
    int has_local_palette;
    int interlaced;
    int width, height;
    int left, top;
    int i;

    // Read image header
    for (i = 0; i < 6; i++) {
        if (gif_get_byte(rctx, &header[i]) != 0)
            return 0;
    }

    // Parse image dimensions and interlacing
    width = (header[1] << 8) | header[0];
    height = (header[3] << 8) | header[2];
    interlaced = header[4] & 0x40;

    if (width <= 0 || height <= 0) {
        rctx->error = IWGIF_INVALID_DIMENSION;
        return 0;
    }

    if (gif_get_byte(rctx, &image_descriptor[0]) != 0)
        return 0;

    if (gif_get_byte(rctx, &image_descriptor[1]) != 0)
        return 0;

    has_local_palette = image_descriptor[0] & 0x80;
    if (has_local_palette) {
        int palette_size = 1 << ((image_descriptor[0] & 0x07) + 1);
        if (!gif_read_color_table(rctx, palette_size, rctx->current_palette)) {
            return 0;
        }
        rctx->using_local_palette = 1;
    }

    // Handle transparency
    if (image_descriptor[0] & 0x01) {
        unsigned char trans_index;
        if (gif_get_byte(rctx, &trans_index) != 0)
            return 0;
        rctx->transparent_index = trans_index;
    }

    // Read LZW code size
    if (gif_get_byte(rctx, &rctx->lzw_code_size) != 0)
        return 0;

    if (rctx->lzw_code_size < 2 || rctx->lzw_code_size > 8) {
        rctx->error = IWGIF_INVALID_LZW_CODE_SIZE;
        return 0;
    }

    // Initialize the screen context
    rctx->width = width;
    rctx->height = height;
    rctx->interlaced = interlaced;

    // Prepare for reading pixel data
    while (1) {
        unsigned char subblock_size;
        if (gif_get_byte(rctx, &subblock_size) != 0)
            return 0;

        if (subblock_size == 0)
            break;

        if (gif_read_subblock(rctx, subblock_size) != 0)
            return 0;
    }

    return 1;
}

int read_and_process_gif_image(struct iwgifrcontext *rctx) {
    // Read image header
    unsigned char image_header[6];
    if (fread(image_header, 1, 6, rctx->file) != 6) {
        return 0;
    }

    // Parse image dimensions and interlacing information
    rctx->image_width = (image_header[0] << 8) | image_header[1];
    rctx->image_height = (image_header[2] << 8) | image_header[3];

    unsigned char packed_fields = image_header[4];
    rctx->is_interlaced = (packed_fields & 0x40) != 0;
    int has_local_color_table = (packed_fields & 0x80) != 0;

    // Check for valid dimensions
    if (rctx->image_width <= 0 || rctx->image_height <= 0) {
        return 0;
    }

    // Initialize color tables if present
    if (has_local_color_table) {
        int color_table_size = 2 << ((packed_fields & 0x07) + 1);
        if (color_table_size > 256) {
            return 0;
        }

        rctx->color_table = (unsigned char *)malloc(color_table_size * 3);
        if (rctx->color_table == NULL) {
            return 0;
        }

        if (fread(rctx->color_table, 1, color_table_size * 3, rctx->file) != (size_t)(color_table_size * 3)) {
            free(rctx->color_table);
            rctx->color_table = NULL;
            return 0;
        }

        // Handle transparency
        rctx->transparent_index = (packed_fields & 0x01) ? (color_table_size - 1) : -1;
    }

    // Read LZW code size
    unsigned char lzw_code_size;
    if (fread(&lzw_code_size, 1, 1, rctx->file) != 1) {
        return 0;
    }

    if (lzw_code_size < 2 || lzw_code_size > 8) {
        return 0;
    }

    // Initialize screen context
    rctx->lzw_code_size = lzw_code_size;
    rctx->current_line = 0;
    rctx->current_pixel = 0;

    // Read pixel data in subblocks
    unsigned char subblock_size;
    while (fread(&subblock_size, 1, 1, rctx->file) == 1) {
        if (subblock_size == 0) {
            break;
        }

        unsigned char subblock_data[256];
        if (fread(subblock_data, 1, subblock_size, rctx->file) != subblock_size) {
            return 0;
        }

        // Process subblock with LZW decoding
        if (!process_lzw_subblock(rctx, subblock_data, subblock_size)) {
            return 0;
        }
    }

    // Finalize image processing
    if (rctx->current_line < rctx->image_height) {
        return 0;
    }

    return 1;
}

int iwgif_read_image(struct iwgifrcontext *rctx) {
    int width, height;
    int has_local_color_table, interlace;
    int color_table_size;

    // Read image header
    if (fread(&width, sizeof(unsigned char), 1, rctx->file) != 1 ||
        fread(&height, sizeof(unsigned char), 1, rctx->file) != 1) {
        return 0;
    }

    unsigned char packed_fields;
    if (fread(&packed_fields, sizeof(unsigned char), 1, rctx->file) != 1) {
        return 0;
    }

    has_local_color_table = (packed_fields & 0x80) >> 7;
    interlace = (packed_fields & 0x40) >> 6;

    // Check for valid dimensions
    if (width <= 0 || height <= 0) {
        return 0;
    }

    // Initialize local color table if present
    if (has_local_color_table) {
        color_table_size = 1 << ((packed_fields & 0x07) + 1);
        rctx->local_color_table = malloc(color_table_size * sizeof(GifColorType));
        if (!rctx->local_color_table) {
            return 0;
        }

        for (int i = 0; i < color_table_size; i++) {
            if (fread(&rctx->local_color_table[i], sizeof(GifColorType), 1, rctx->file) != 1) {
                return 0;
            }
        }

        // Handle transparency if needed
        if (rctx->global_color_table && rctx->transparent_index >= 0) {
            rctx->local_color_table[rctx->transparent_index].Red = 0;
            rctx->local_color_table[rctx->transparent_index].Green = 0;
            rctx->local_color_table[rctx->transparent_index].Blue = 0;
        }
    }

    // Read LZW code size
    unsigned char lzw_code_size;
    if (fread(&lzw_code_size, sizeof(unsigned char), 1, rctx->file) != 1) {
        return 0;
    }

    // Validate LZW code size
    if (lzw_code_size < 1 || lzw_code_size > 8) {
        return 0;
    }

    // Initialize screen context
    rctx->image_width = width;
    rctx->image_height = height;
    rctx->interlace = interlace;
    rctx->lzw_code_size = lzw_code_size;
    rctx->using_local_color_table = has_local_color_table;

    int success = 1;
    unsigned char subblock_size;
    do {
        if (fread(&subblock_size, sizeof(unsigned char), 1, rctx->file) != 1) {
            success = 0;
            break;
        }

        if (subblock_size > 0) {
            unsigned char *subblock_data = malloc(subblock_size);
            if (!subblock_data) {
                success = 0;
                break;
            }

            if (fread(subblock_data, sizeof(unsigned char), subblock_size, rctx->file) != subblock_size) {
                free(subblock_data);
                success = 0;
                break;
            }

            // Process subblock using LZW decoding
            success = iwgif_decode_subblock(rctx, subblock_data, subblock_size);
            free(subblock_data);
            if (!success) {
                break;
            }
        }
    } while (subblock_size > 0);

    return success;
}

int iwgif_read_process_image(struct iwgifrcontext *rctx) {
    uint8_t header[6];
    uint8_t packed_fields;
    int has_local_color_table;
    int interlaced = 0;
    int i;
    int ret = 0;

    if (fread(header, 1, 6, rctx->fp) != 6)
        return 0;

    rctx->image.left = (header[1] << 8) | header[0];
    rctx->image.top = (header[3] << 8) | header[2];
    rctx->image.width = (header[3] << 8) | header[2];
    rctx->image.height = (header[5] << 8) | header[4];

    packed_fields = header[5];
    has_local_color_table = (packed_fields & 0x80) >> 7;
    interlaced = (packed_fields & 0x40) >> 6;

    if (rctx->image.width <= 0 || rctx->image.height <= 0)
        return 0;

    if (has_local_color_table) {
        int color_table_size = 1 << ((packed_fields & 0x07) + 1);
        rctx->local_color_table = malloc(color_table_size * 3);
        if (!rctx->local_color_table)
            return 0;

        if (fread(rctx->local_color_table, 3, color_table_size, rctx->fp) != (size_t)color_table_size) {
            free(rctx->local_color_table);
            return 0;
        }
    }

    if (packed_fields & 0x1) {
        // Transparency handling
        rctx->transparent_index = 0;
    }

    rctx->lzw_code_size = fgetc(rctx->fp);
    if (rctx->lzw_code_size < 2 || rctx->lzw_code_size > 8)
        return 0;

    if (!iwgif_init_screen_context(rctx))
        return 0;

    while (1) {
        uint8_t subblock_size;
        if (fread(&subblock_size, 1, 1, rctx->fp) != 1)
            break;

        if (subblock_size == 0)
            break;

        if (!iwgif_read_subblock(rctx, subblock_size, interlaced))
            break;

        if (rctx->error)
            break;
    }

    if (!rctx->error)
        ret = 1;

    return ret;
}
